using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 [InitializeOnLoad] public static class TerrainTractorTestAuthoring {
  const string ScenePath="Assets/Scenes/AlpsTerrainTest.unity",Folder="Assets/Snowglow/Levels/AlpsTerrainTest",Log="Logs/AlpsTerrainTest",Key="Snowglow.TerrainTestChecks";
  static TerrainTractorTestAuthoring(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=state=>{if(state==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool(Key,false)){SessionState.SetBool(Key,false);try{Check(Hash(SaveStore.PathName)==SessionState.GetString(Key+".Save",""),"real profile preserved");Check(Hash(SaveStore.PathName+".bak")==SessionState.GetString(Key+".Backup",""),"backup preserved");File.AppendAllText(Log+"/Play.txt","\nReal save and backup unchanged after Play exit.");}catch(Exception e){File.AppendAllText(Log+"/Play.txt","\nFAIL: "+e);}}};}
  static void Check(bool b,string why){if(!b)throw new InvalidOperationException("Terrain tractor test: "+why);}
  static string Hash(string path){if(!File.Exists(path))return "missing";using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(path)));}
  [MenuItem("Snowglow/Developer/Play terrain test directly")] static void Enable(){var asset=AssetDatabase.LoadAssetAtPath<SceneAsset>(ScenePath);Check(asset,"create terrain test first");EditorSceneManager.playModeStartScene=asset;}
  [MenuItem("Snowglow/Developer/Play current scene normally")] static void Disable()=>EditorSceneManager.playModeStartScene=null;
  static void Tick(){try{
   if(File.Exists(Log+".request")&&!EditorApplication.isPlayingOrWillChangePlaymode&&!EditorApplication.isCompiling&&!EditorApplication.isUpdating){var action=File.ReadAllText(Log+".request").Trim();File.Delete(Log+".request");Directory.CreateDirectory(Log);if(action=="build")Build();else if(action=="replace")TerrainTestRevision.Apply();else if(action=="mountains")TerrainTestMountains.Apply();else if(action=="mountainsretry")TerrainTestMountains.Retry();else if(action=="mountaingap")TerrainTestMountains.AddGap();else if(action=="mountaingapcorrect")TerrainTestMountains.CorrectGapOrientation();else if(action=="mountainseat")TerrainTestMountainSeating.Apply();else if(action=="play")StartChecks();else throw new InvalidOperationException("Unknown action "+action);}
   if(!SessionState.GetBool(Key,false)||!EditorApplication.isPlaying||EditorApplication.isCompiling)return;var tests=UnityEngine.Object.FindFirstObjectByType<TerrainTractorTest>();if(!tests||!tests.tractor.Body)return;float elapsed=Time.fixedTime-SessionState.GetFloat(Key+".SimStarted",0);Check((float)EditorApplication.timeSinceStartup-SessionState.GetFloat(Key+".Started",0)<120,"Play timeout");int stage=SessionState.GetInt(Key+".Stage",0);
   if(stage==0){Check(SceneManager.GetActiveScene().path==ScenePath,"Play starts test scene directly");Check(!PrototypeSession.Instance&&UnityEngine.Object.FindObjectsByType<PrototypeSession>(FindObjectsSortMode.None).Length==0,"no game session/save routing");Check(UnityEngine.Object.FindObjectsByType<MachineController>(FindObjectsSortMode.None).Length==1,"one tractor");SessionState.SetFloat(Key+".Started",(float)EditorApplication.timeSinceStartup);SessionState.SetFloat(Key+".SimStarted",Time.fixedTime);SessionState.SetInt(Key+".Stage",1);}
   else if(stage==1&&elapsed>3){Check(tests.tractor.wheels.All(w=>w.GetGroundHit(out var hit)),"four wheels supported on actual terrain");SessionState.SetFloat(Key+".Z",tests.tractor.transform.position.z);tests.diagnosticDrive=true;SessionState.SetInt(Key+".Stage",2);SessionState.SetFloat(Key+".Started",(float)EditorApplication.timeSinceStartup);SessionState.SetFloat(Key+".SimStarted",Time.fixedTime);}
   else if(stage==2&&elapsed>4){Check(tests.tractor.transform.position.z-SessionState.GetFloat(Key+".Z",0)>1,"shared production handling propels tractor");Check(tests.tractor.Body.linearVelocity.magnitude>1,"tractor moving");tests.diagnosticDrive=false;tests.input.Clear();float speed=tests.tractor.Body.linearVelocity.magnitude;SessionState.SetFloat(Key+".Speed",speed);SessionState.SetFloat(Key+".Started",(float)EditorApplication.timeSinceStartup);SessionState.SetFloat(Key+".SimStarted",Time.fixedTime);SessionState.SetInt(Key+".Stage",3);}
   else if(stage==3&&elapsed>.4f){Check(tests.tractor.Body.linearVelocity.magnitude>.5f,"coasts after release");tests.tractor.RecoverToDepot();Check(tests.tractor.Body.linearVelocity.sqrMagnitude<.001f&&tests.tractor.Body.angularVelocity.sqrMagnitude<.001f,"reset clears motion");File.WriteAllText(Log+"/Play.txt","PASS: direct Play scene, no game session, one tractor, all four wheel contacts, production drive acceleration, release coasting and reset motion checks. Test input cleared; no snow/UI/economy or player saves.");EditorApplication.isPlaying=false;}
  }catch(Exception e){Directory.CreateDirectory(Log);File.WriteAllText(Log+"/Validation.txt","FAIL: "+e);Debug.LogException(e);if(EditorApplication.isPlaying&&SessionState.GetBool(Key,false))EditorApplication.isPlaying=false;}}
  static void Build(){Check(!File.Exists(ScenePath),"test scene already exists; no implicit overwrite");var prior=SceneManager.GetActiveScene();if(prior.isDirty)Check(EditorSceneManager.SaveScene(prior,Log+"/Unsaved-before.unity",true),"unsaved scene backup");string source="SourceAssets/AlpsRebuild/Snow_District_Alps_Town_Terrain.blend";Check(Hash(source)==Hash("C:/Users/jrbar/Downloads/Snow_District_Alps_Town_Terrain.blend"),"attached Blender matches retained source/export provenance");DirectionBufferChecks.Run();if(prior.GetRootGameObjects().Any(g=>g.GetComponentsInChildren<PrototypeSession>(true).Length>0))RecoveryPhysicsChecks.Run();Directory.CreateDirectory(Folder);AssetDatabase.Refresh();var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
   var terrain=(GameObject)PrefabUtility.InstantiatePrefab(AlpsRebuildAssets.Find("TerrainBase").prefab,scene);terrain.name="Original attached terrain | 1:1 metres";terrain.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);terrain.transform.localScale=Vector3.one;var filter=terrain.GetComponentInChildren<MeshFilter>();var collision=filter.gameObject.AddComponent<MeshCollider>();collision.sharedMesh=filter.sharedMesh;Physics.SyncTransforms();Check(collision.Raycast(new Ray(new Vector3(0,600,0),Vector3.down),out var ground,1000),"terrain centre collision");
   var queryData=new TerrainData{heightmapResolution=257,size=new Vector3(1000,400,1000)};var heights=new float[257,257];using(var reader=new BinaryReader(File.OpenRead("SourceAssets/AlpsRebuild/TerrainHeight_257_f32le.raw")))for(int z=0;z<257;z++)for(int x=0;x<257;x++)heights[z,x]=reader.ReadSingle()/400;queryData.SetHeights(0,0,heights);AssetDatabase.CreateAsset(queryData,Folder+"/OriginalScaleCameraHeights.asset");var query=Terrain.CreateTerrainGameObject(queryData);query.name="Camera terrain queries | invisible, no collision";query.transform.position=new Vector3(-500,0,-500);query.GetComponent<Terrain>().drawHeightmap=false;query.GetComponent<Terrain>().drawTreesAndFoliage=false;query.GetComponent<TerrainCollider>().enabled=false;
   var tractor=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Snowglow/Catalog/Prefabs/GoldenTractor-Starter.prefab"),scene);tractor.name="Terrain test tractor";tractor.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var machine=tractor.GetComponent<MachineController>();float bottom=machine.wheels.Min(w=>w.transform.TransformPoint(w.center).y-w.radius-w.suspensionDistance*.5f);tractor.transform.position=Vector3.up*(ground.point.y-bottom+.15f);
   var controls=new GameObject("Test driving | no game session or saves");var input=controls.AddComponent<PrototypeInput>();var driver=controls.AddComponent<TerrainTractorTest>();driver.tractor=machine;driver.input=input;
   var cameraObject=new GameObject("Test camera",typeof(Camera),typeof(AudioListener),typeof(CameraRig));var camera=cameraObject.GetComponent<Camera>();camera.farClipPlane=2200;camera.nearClipPlane=.15f;camera.backgroundColor=new Color(.6f,.73f,.82f);camera.clearFlags=CameraClearFlags.SolidColor;cameraObject.tag="MainCamera";var rig=cameraObject.GetComponent<CameraRig>();rig.view=camera;rig.terrain=query.GetComponent<Terrain>();rig.SetMode(CameraMode.Orbit);driver.cameraRig=rig;rig.UpdateForTarget(tractor.transform,.1f,false);
   var light=new GameObject("Sun").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.1f;light.shadows=LightShadows.Soft;light.transform.rotation=Quaternion.Euler(40,-35,0);RenderSettings.ambientLight=new Color(.65f,.72f,.8f);RenderSettings.fog=false;
   Check(EditorSceneManager.SaveScene(scene,ScenePath),"save empty terrain test");scene=EditorSceneManager.OpenScene(ScenePath);Check(scene.GetRootGameObjects().Length==6,"only terrain, tractor, camera, sun and invisible test/query helpers");Check(!scene.GetRootGameObjects().Any(g=>g.GetComponent<PrototypeSession>()||g.GetComponent<SnowField>()),"no production session or snow field");Enable();File.WriteAllText(Log+"/Validation.txt","PASS: empty standalone test scene saved/reopened, original attached mesh at 1:1 scale, one existing tractor, physical terrain collision, hidden original-scale camera query, camera and Sun. Editor Play start overridden to this scene; build settings unchanged. W/S forward/reverse, A/D steer, Space brake, R reset, C camera; orbit right-drag/scroll. No menus, town scenery, snow simulation or save access.");
  }
  static void StartChecks(){Check(SceneManager.GetActiveScene().path==ScenePath&&!SceneManager.GetActiveScene().isDirty,"clean test scene open");SessionState.SetString(Key+".Save",Hash(SaveStore.PathName));SessionState.SetString(Key+".Backup",Hash(SaveStore.PathName+".bak"));SessionState.SetBool(Key,true);SessionState.SetInt(Key+".Stage",0);SessionState.SetFloat(Key+".Started",(float)EditorApplication.timeSinceStartup);SessionState.SetFloat(Key+".SimStarted",Time.fixedTime);EditorApplication.isPlaying=true;}
 }
